def from_roman(s):
    if not s or not isinstance(s, str):
        raise ValueError("Invalid Roman numeral")
    # Check for uppercase only
    if not s.isupper():
        raise ValueError("Invalid Roman numeral: must be uppercase")

    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Validate characters
    for char in s:
        if char not in roman_map:
            raise ValueError(f"Invalid character: {char}")

    # Check for standard form by converting and back-converting
    # First, basic conversion
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and roman_map[s[i]] < roman_map[s[i+1]]:
            total += roman_map[s[i+1]] - roman_map[s[i]]
            i += 2
        else:
            total += roman_map[s[i]]
            i += 1

    if total < 1 or total > 3999:
        raise ValueError("Roman numeral out of range 1-3999")

    # Now validate the standard form by back-converting
    # Build standard Roman numeral from the integer
    val_sym = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    standard = ''
    remaining = total
    for val, sym in val_sym:
        while remaining >= val:
            standard += sym
            remaining -= val

    if standard != s:
        raise ValueError("Invalid standard form")

    return total

# Test examples
tests = [
    ("III", 3),
    ("IV", 4),
    ("IX", 9),
    ("LVIII", 58),
    ("MCMXCIV", 1994),
]

for roman, expected in tests:
    result = from_roman(roman)
    assert result == expected, f"from_roman('{roman}') = {result}, expected {expected}"
    print(f"from_roman('{roman}') = {result} ✓")

# Test invalid cases
invalid_cases = ["IIII", "IC", ""]
for roman in invalid_cases:
    try:
        result = from_roman(roman)
        print(f"from_roman('{roman}') = {result} - FAILED (should have raised ValueError)")
    except ValueError:
        print(f"from_roman('{roman}') raised ValueError ✓")

print("ALL TESTS PASSED")

